use std::rc::Rc;use std::cell::RefCell;impl Solution{pub fn build_tree(ino:Vec<i32>,post:Vec<i32>)->Option<Rc<RefCell<TreeNode>>>{fn f(ino:&[i32],l:i32,r:i32,post:&[i32],i:&mut i32)->Option<Rc<RefCell<TreeNode>>>{if l>r{return None}let v=post[*i as usize];*i-=1;let mut k=l;while ino[k as usize]!=v{k+=1}let right=f(ino,k+1,r,post,i);let left=f(ino,l,k-1,post,i);Some(Rc::new(RefCell::new(TreeNode{val:v,left,right})))}let mut i=post.len()as i32-1;f(&ino,0,ino.len()as i32-1,&post,&mut i)}}
